    pr.lib_name(g)
}

// ---------------------------------------------------------------- views

/// The categories that are views of the model or of paper.
pub const VIEW_CATEGORIES: &[&str] = &["level", "planview", "section", "elevation", "view3d", "sheet", "schedule"];

pub fn is_view_category(c: &str) -> bool {
    VIEW_CATEGORIES.contains(&c)
}

/// A plan: a level's own plan (the level) or a plan view of it.
pub fn is_plan(pr: &Project, id: u64) -> bool {
    matches!(cat_of(pr, id).as_str(), "level" | "planview")
}

/// The level a plan shows (a level is its own plan).
pub fn plan_level(pr: &Project, id: u64) -> Option<u64> {
    crate::model::level_of_view(pr, id)
}

/// A view's name as messages give it: a sheet by its number.
pub fn view_name(pr: &Project, id: u64) -> String {
    match pr.el(id) {
        Some(e) if cat(e) == "sheet" => s_of(e, "number").unwrap_or("").to_string(),
        Some(e) => s_of(e, "name").unwrap_or("").to_string(),
        None => String::new(),
    }
}

/// A view given by id (any element: what it isn't is the command's to say) or by name: a level's,
/// a plan view's, a section's, an elevation's, a 3D view's or a schedule's name, or a sheet's
/// number. "`view`: X is not a view" for an id the project hasn't (or what is neither a number
/// nor text), "no view named `X`" for a name none has.
pub fn find_view(pr: &Project, cmd: &str, key: &str, v: &Value) -> R<u64> {
    let not = || format!("{}: `{}`: {} is not a view", cmd, key, v.to_compact());
    match v {
        Value::Num(_) => {
            let id = id_of(v).ok_or_else(not)?;
            if pr.elements.contains_key(&id) {
                Ok(id)
            } else {
                Err(not())
            }
        }
        Value::Str(s) => {
            if let Some(id) = find_view_named(pr, s) {
                return Ok(id);
            }
            if let Ok(id) = s.trim().parse::<u64>() {
                if pr.elements.contains_key(&id) {
                    return Ok(id);
                }
            }
            if let Some(g) = crate::model::normalize_guid(s) {
                if let Some(id) = pr.find_guid(&g) {
                    return Ok(id);
                }
            }
            Err(format!("{}: no view named `{}`", cmd, s))
        }
        _ => Err(not()),
    }
}

/// The view of this name (a sheet by its number), the first by id.
pub fn find_view_named(pr: &Project, name: &str) -> Option<u64> {
    for (id, e) in &pr.elements {
        let c = cat(e);
        if c == "sheet" {
            if s_of(e, "number") == Some(name) {
                return Some(*id);
            }
        } else if is_view_category(c) && s_of(e, "name") == Some(name) {
            return Some(*id);
        }
    }
    None
}

/// The `view` parameter (or `key`), if given (null is not given).
pub fn view_param(pr: &Project, cmd: &str, p: &Value, key: &str) -> R<Option<u64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => find_view(pr, cmd, key, v).map(Some),
    }
}

/// The lowest level, the plan commands draw in without a view.
pub fn default_plan(pr: &Project) -> Option<u64> {
    crate::model::default_level(pr)
}

/// The name the default 3D view goes by.
pub const DEFAULT_3D: &str = "{3D}";

/// Whether a view name is the default 3D view's (in any case).
pub fn is_default_3d_name(s: &str) -> bool {
    s.to_lowercase() == "{3d}"
}

/// The default 3D view, if it has come to be.
pub fn default_3d(pr: &Project) -> Option<u64> {
    pr.elements
        .iter()
        .find(|(_, e)| cat(e) == "view3d" && s_of(e, "name") == Some(DEFAULT_3D) && e.get("camera").is_none())
        .map(|(id, _)| *id)
        .or_else(|| {
            pr.elements
                .iter()
                .find(|(_, e)| cat(e) == "view3d" && s_of(e, "name") == Some(DEFAULT_3D))
                .map(|(id, _)| *id)
        })
}

/// The default 3D view, made as the original makes it when it is first changed or placed.
pub fn ensure_default_3d(pr: &mut Project) -> u64 {
    if let Some(id) = default_3d(pr) {
        return id;
    }
    let id = pr.alloc_id();
    pr.elements.insert(
        id,
        jobj! {
            "guid" => crate::rand::guid(),
            "category" => "view3d",
            "name" => DEFAULT_3D,
            "azimuth" => -45.0,
            "elevation" => 30.0,
        },
    );
    id
}

/// Every element of a category, by id.
pub fn ids_of(pr: &Project, c: &str) -> Vec<u64> {
    pr.ids_of(c)
}

/// An element's field as an object, made empty where it isn't one (`graphics`, `crop`…).
pub fn obj_field<'a>(e: &'a mut Value, k: &str) -> &'a mut Map {
    if !matches!(e.get(k), Some(Value::Obj(_))) {
        e.set(k, Value::obj());
    }
    e.get_mut(k).unwrap().as_obj_mut().unwrap()
}

// ---------------------------------------------------------------- languages

/// The project's language code (en by default).
pub fn lang(pr: &Project) -> String {
    pr.language()
}

/// A word of the project's language from a table of (en, pt, es, sv, cs, fr, nl, de, it).
pub fn word(pr: &Project, t: [&'static str; 9]) -> &'static str {
    let i = crate::project::LANGS.iter().position(|l| *l == pr.language()).unwrap_or(0);
    t[i]
}
//! A stand-in for the model geometry the views and the annotation read (ARCH and STRUCTURE own
//! the real thing): a wall's type, thickness, core, location line and centre line, its faces, the
//! heights an element spans, and outlines in plan of what the model builds.

use super::common::*;
use crate::json::Value;
use crate::project::Project;

/// A wall type's entry in `types.wall` (its `thickness`, `layers`).
pub fn wall_type<'a>(pr: &'a Project, e: &Value) -> Option<&'a Value> {
    let name = lib_ref_name(pr, e, "type")?;
    pr.section("types")?.get("wall")?.get(&name)
}

/// A type of a category's entry in `types.<cat>` by the element's `type` GUID.
pub fn type_entry<'a>(pr: &'a Project, cat: &str, e: &Value) -> Option<&'a Value> {
    let name = lib_ref_name(pr, e, "type")?;
    pr.section("types")?.get(cat)?.get(&name)
}

pub fn wall_thickness(pr: &Project, e: &Value) -> f64 {
    wall_type(pr, e).and_then(|t| f_of(t, "thickness")).unwrap_or(200.0)
}

/// The wall's layers, exterior first: (function, thickness).
pub fn wall_layers(pr: &Project, e: &Value) -> Vec<(String, f64)> {
    let Some(t) = wall_type(pr, e) else { return Vec::new() };
    let Some(a) = t.get("layers").and_then(|l| l.as_arr()) else { return Vec::new() };
    a.iter()
        .map(|l| (s_of(l, "function").unwrap_or("").to_string(), f_of(l, "thickness").unwrap_or(0.0)))
        .collect()
}

/// The core's two faces, as distances from the exterior face: the span of its structure layers
/// (the whole wall where it has none).
pub fn wall_core(pr: &Project, e: &Value) -> (f64, f64) {
    let t = wall_thickness(pr, e);
    let layers = wall_layers(pr, e);
    let mut at = 0.0;
    let mut core: Option<(f64, f64)> = None;
    for (f, th) in &layers {
        if f == "structure" {
            core = Some(match core {
                None => (at, at + th),
                Some((a, _)) => (a, at + th),
            });
        }
        at += th;
    }
    core.unwrap_or((0.0, t))
}

/// How far the wall's centre line lies left of its location line (the line its `start` and `end`
/// give), as its `location` says. The exterior face is the left one.
pub fn centre_offset(pr: &Project, e: &Value) -> f64 {
    let t = wall_thickness(pr, e);
    let (a, b) = wall_core(pr, e);
    match s_of(e, "location").unwrap_or("centre") {
        "exterior-finish" => -t / 2.0,
        "interior-finish" => t / 2.0,
        "core-centre" => (a + b) / 2.0 - t / 2.0,
        "exterior-core" => a - t / 2.0,
        "interior-core" => b - t / 2.0,
        _ => 0.0,
    }
}

/// A wall's line in plan: straight from `start` to `end`, or an arc turning `arc` degrees
/// counter-clockwise between them.
#[derive(Clone, Copy, Debug)]
pub struct WallLine {
    pub start: [f64; 2],
    pub end: [f64; 2],
    /// Degrees turned counter-clockwise (0: straight).
    pub arc: f64,
}

impl WallLine {
    pub fn is_arc(&self) -> bool {
        self.arc.abs() > 1e-9
    }
    pub fn length(&self) -> f64 {
        let c = dist(self.start, self.end);
        if !self.is_arc() {
            return c;
        }
        let (_, r) = self.circle().unwrap();
        r * self.arc.abs().to_radians()
    }
    /// The arc's centre and radius.
    pub fn circle(&self) -> Option<([f64; 2], f64)> {
        if !self.is_arc() {
            return None;
        }
        arc_circle(self.start, self.end, self.arc)
    }
    /// The line moved `d` to its left (an arc: concentric, its radius less `d` for a
    /// counter-clockwise one).
    pub fn offset(&self, d: f64) -> WallLine {
        if !self.is_arc() {
            let n = left_normal(self.start, self.end);
            return WallLine { start: add(self.start, mul(n, d)), end: add(self.end, mul(n, d)), arc: 0.0 };
        }
        let (c, _) = self.circle().unwrap();
        // left of a counter-clockwise arc is toward its centre
        let s = if self.arc > 0.0 { -d } else { d };
        let move_out = |p: [f64; 2]| {
            let v = sub(p, c);
            let l = norm(v);
            add(c, mul(v, (l + s) / l))
        };
        WallLine { start: move_out(self.start), end: move_out(self.end), arc: self.arc }
    }
    /// Points along it, `n` segments for an arc.
    pub fn points(&self, n: usize) -> Vec<[f64; 2]> {
        if !self.is_arc() {
            return vec![self.start, self.end];
        }
        let (c, r) = self.circle().unwrap();
        let a0 = (self.start[1] - c[1]).atan2(self.start[0] - c[0]);
        let sweep = self.arc.to_radians();
        (0..=n).map(|i| {
            let a = a0 + sweep * i as f64 / n as f64;
            [c[0] + r * a.cos(), c[1] + r * a.sin()]
        }).collect()
    }
}

/// The centre and radius of the arc from `a` to `b` turning `deg` degrees counter-clockwise.
pub fn arc_circle(a: [f64; 2], b: [f64; 2], deg: f64) -> Option<([f64; 2], f64)> {
    let t = deg.to_radians();
    let c = dist(a, b);
    if c == 0.0 || t == 0.0 {
        return None;
    }
    let r = c / (2.0 * (t / 2.0).sin().abs());
    let m = mid(a, b);
    // distance from the chord's middle to the centre, toward the left of a→b for a turn under 180
    let h = r * (t / 2.0).cos();
    let n = left_normal(a, b);
    let sign = if t > 0.0 { 1.0 } else { -1.0 };
    Some((add(m, mul(n, h * sign)), r))
}

/// The wall's location line, as its `start`, `end` and `arc` give it.
pub fn location_line(e: &Value) -> WallLine {
    WallLine {
        start: pt_of(e, "start").unwrap_or([0.0, 0.0]),
        end: pt_of(e, "end").unwrap_or([0.0, 0.0]),
        arc: f_of(e, "arc").unwrap_or(0.0),
    }
}

/// The wall's centre line (its location line moved as its `location` says).
pub fn centre_line(pr: &Project, e: &Value) -> WallLine {
    location_line(e).offset(centre_offset(pr, e))
}

/// The wall's left (exterior) and right faces, ends as the wall's own (no joins).
pub fn faces(pr: &Project, e: &Value) -> (WallLine, WallLine) {
    let c = centre_line(pr, e);
    let t = wall_thickness(pr, e);
    (c.offset(t / 2.0), c.offset(-t / 2.0))
}

// ---------------------------------------------------------------- heights

pub fn level_elevation(pr: &Project, e: &Value, k: &str) -> Option<f64> {
    let id = ref_id(pr, e, k)?;
    f_of(pr.el(id)?, "elevation")
}

/// The heights a wall (or a column) spans: its base over its level and its top at its top level
/// (with `top_offset`) or `height` over its base.
pub fn base_top(pr: &Project, e: &Value) -> (f64, f64) {
    let lv = level_elevation(pr, e, "level").unwrap_or(0.0);
    let base = lv + f_of(e, "base_offset").unwrap_or(0.0);
    let top = match level_elevation(pr, e, "top_level") {
        Some(t) => t + f_of(e, "top_offset").unwrap_or(0.0),
        None => base + f_of(e, "height").unwrap_or(3000.0),
    };
    (base, top)
}

// ---------------------------------------------------------------- outlines in plan

/// The outline in plan of a built element where the stand-in knows it: a wall's (its faces, no
/// joins), a floor's, ceiling's or roof's boundary, a column's or footing's rectangle or circle.
pub fn outline(pr: &Project, id: u64) -> Option<Vec<[f64; 2]>> {
    let e = pr.el(id)?;
    match cat(e) {
        "wall" => {
            let (l, r) = faces(pr, e);
            let mut pts = l.points(32);
            let mut back = r.points(32);
            back.reverse();
            pts.extend(back);
            Some(pts)
        }
        "floor" | "ceiling" | "roof" | "shaft" => pts_of(e, "boundary"),
        "column" | "structural_column" | "structuralcolumn" | "footing" => {
            let c = pt_of(e, "at")?;
            let cat_key = match cat(e) {
                "structuralcolumn" => "structural_column",
                x => x,
            };
            let t = type_entry(pr, cat_key, e);
            let w = t.and_then(|t| f_of(t, "width")).unwrap_or(400.0);
            let d = t.and_then(|t| f_of(t, "depth")).unwrap_or(w);
            let round = t.and_then(|t| t.get("round")).and_then(|r| r.as_bool()).unwrap_or(false);
            let a = f_of(e, "angle").unwrap_or(0.0).to_radians();
            if round {
                return Some((0..32).map(|i| {
                    let t = i as f64 / 32.0 * std::f64::consts::TAU;
                    [c[0] + w / 2.0 * t.cos(), c[1] + w / 2.0 * t.sin()]
                }).collect());
            }
            let (ca, sa) = (a.cos(), a.sin());
            Some([[-w / 2.0, -d / 2.0], [w / 2.0, -d / 2.0], [w / 2.0, d / 2.0], [-w / 2.0, d / 2.0]]
                .iter()
                .map(|p| [c[0] + p[0] * ca - p[1] * sa, c[1] + p[0] * sa + p[1] * ca])
                .collect())
        }
        _ => None,
    }
}

/// The south-west and north-east corners round some points.
pub fn bounds(pts: &[[f64; 2]]) -> Option<([f64; 2], [f64; 2])> {
    let mut it = pts.iter();
    let f = *it.next()?;
    let (mut lo, mut hi) = (f, f);
    for p in it {
        lo = [lo[0].min(p[0]), lo[1].min(p[1])];
        hi = [hi[0].max(p[0]), hi[1].max(p[1])];
    }
    Some((lo, hi))
}

// ---------------------------------------------------------------- vectors

pub fn add(a: [f64; 2], b: [f64; 2]) -> [f64; 2] {
    [a[0] + b[0], a[1] + b[1]]
}
pub fn sub(a: [f64; 2], b: [f64; 2]) -> [f64; 2] {
    [a[0] - b[0], a[1] - b[1]]
}
pub fn mul(a: [f64; 2], k: f64) -> [f64; 2] {
    [a[0] * k, a[1] * k]
}
pub fn dot(a: [f64; 2], b: [f64; 2]) -> f64 {
    a[0] * b[0] + a[1] * b[1]
}
pub fn cross(a: [f64; 2], b: [f64; 2]) -> f64 {
    a[0] * b[1] - a[1] * b[0]
}
pub fn norm(a: [f64; 2]) -> f64 {
    (a[0] * a[0] + a[1] * a[1]).sqrt()
}
pub fn dist(a: [f64; 2], b: [f64; 2]) -> f64 {
    norm(sub(a, b))
}
pub fn mid(a: [f64; 2], b: [f64; 2]) -> [f64; 2] {
    [(a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0]
}
pub fn unit(a: [f64; 2]) -> [f64; 2] {
    let l = norm(a);
    if l == 0.0 {
        [0.0, 0.0]
    } else {
        [a[0] / l, a[1] / l]
    }
}
/// The unit normal to the left of the way from `a` to `b`.
pub fn left_normal(a: [f64; 2], b: [f64; 2]) -> [f64; 2] {
    let d = unit(sub(b, a));
    [-d[1], d[0]]
}

#!/usr/bin/env python3
"""Run each command line of a file (or stdin) separately on the original (and optionally mine).
usage: each.py [-m] [-b] [-f in.bimcraft] [-s 'setup cmd']... < cmds.txt
  -m: run mine instead; -b: run both and mark differences; -f: open this project first.
Each line: a command `id {json}` (or several separated by ' ;; ')."""
import os, subprocess, sys, tempfile, shutil, re
ORIG = '/workspace/executable'
MINE = os.environ['MINE'] if 'MINE' in os.environ else '/nonexistent-set-MINE'
G = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
a = sys.argv[1:]
exes = [ORIG]
infile = None
setup = []
both = False
while a:
    if a[0] == '-m': exes = [MINE]; a = a[1:]
    elif a[0] == '-b': exes = [ORIG, MINE]; both = True; a = a[1:]
    elif a[0] == '-f': infile = a[1]; a = a[2:]
    elif a[0] == '-s': setup.append(a[1]); a = a[2:]
    else: break
src = open(a[0]) if a else sys.stdin
lines = [l.rstrip('\n') for l in src if l.strip() and not l.startswith('#')]
def norm(s):
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    return G.sub(rep, s)
same = 0
for l in lines:
    outs = []
    for exe in exes:
        d = tempfile.mkdtemp(prefix='e', dir=os.environ.get('SCRATCH'))
        args = [exe, 'run']
        if infile:
            shutil.copy(infile, d)
            args.append(os.path.basename(infile))
        for s in setup:
            args += ['--cmd', s]
        for c in l.split(' ;; '):
            args += ['--cmd', c]
        p = subprocess.run(args, cwd=d, capture_output=True, timeout=120)
        shutil.rmtree(d)
        o = p.stdout.decode('utf-8', 'replace').strip().split('\n')
        o = [x for x in o if x][-1:] if (infile or setup) else o
        outs.append(norm(('OUT ' + '\n    '.join(o) if any(o) else '') + (' ERR ' + p.stderr.decode('utf-8', 'replace').strip() if p.stderr else '') + ' [%d]' % p.returncode))
    if both:
        if outs[0] == outs[1]:
            same += 1
            print('SAME', l[:150])
        else:
            print('DIFF', l)
            print('  orig:', outs[0])
            print('  mine:', outs[1])
    else:
        print('>>', l)
        print('  ', outs[0])
if both:
    print('%d/%d same' % (same, len(lines)))
#!/usr/bin/env python3
"""Run the original and my build with the same args in fresh dirs; diff normalized outputs.
usage: cmp.py [-q] [-f file_to_copy]... -- args...
"""
import os, re, subprocess, sys, tempfile, shutil, difflib
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/workspace/target/release/bimcraft-cli')
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m)+1)
        return m[g]
    s = GUID.sub(rep, s)
    s = re.sub(r"\.tmp[A-Za-z0-9]{6}", ".tmpXXXXXX", s)
    s = re.sub(r"'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d'", "'<TIMESTAMP>'", s)
    # IFC GlobalIds
    gm = {}
    def grep(mo):
        g = mo.group(1)
        if g not in gm: gm[g] = 'GID-%d' % (len(gm)+1)
        return "('" + gm[g] + "'"
    s = re.sub(r"\('([0-9A-Za-z_$]{22})'", grep, s)
    return s
def run(exe, args, files, stdin):
    d = tempfile.mkdtemp(prefix='cmp')
    for f in files: shutil.copy(f, d)
    before = set(os.listdir(d))
    p = subprocess.run([exe] + args, cwd=d, capture_output=True, input=stdin, timeout=120)
    out = {'stdout': p.stdout.decode('utf-8','replace'), 'stderr': p.stderr.decode('utf-8','replace'), 'code': p.returncode}
    fl = {}
    for root, dirs, fs in os.walk(d):
        for f in fs:
            full = os.path.join(root, f)
            rel = os.path.relpath(full, d)
            if rel in before: 
                pass
            try: fl[rel] = open(full,'rb').read()
            except Exception as e: fl[rel] = b'<unreadable>'
    shutil.rmtree(d)
    return out, fl
def main():
    a = sys.argv[1:]
    quiet = False; files = []; stdin = None
    while a and a[0] != '--':
        if a[0] == '-q': quiet = True; a = a[1:]
        elif a[0] == '-f': files.append(a[1]); a = a[2:]
        elif a[0] == '-i': stdin = open(a[1],'rb').read(); a = a[2:]
        else: break
    if a and a[0] == '--': a = a[1:]
    o, of = run(ORIG, a, files, stdin)
    m, mf = run(MINE, a, files, stdin)
    ok = True
    for k in ('code', 'stdout', 'stderr'):
        x = norm(str(o[k])); y = norm(str(m[k]))
        if x != y:
            ok = False
            print(f'--- {k} differs')
            for l in list(difflib.unified_diff(x.splitlines(), y.splitlines(), 'orig', 'mine', lineterm='', n=1))[:40]:
                print(l[:300])
    for f in sorted(set(of) | set(mf)):
        if f not in of: ok = False; print(f'--- file {f} only in mine'); continue
        if f not in mf: ok = False; print(f'--- file {f} only in orig'); continue
        x, y = of[f], mf[f]
        try:
            xs = norm(x.decode('utf-8')); ys = norm(y.decode('utf-8'))
        except UnicodeDecodeError:
            if x != y: ok = False; print(f'--- binary file {f} differs ({len(x)} vs {len(y)} bytes)')
            continue
        if xs != ys:
            ok = False
            print(f'--- file {f} differs')
            for l in list(difflib.unified_diff(xs.splitlines(), ys.splitlines(), 'orig', 'mine', lineterm='', n=1))[:60]:
                print(l[:300])
    print('SAME' if ok else 'DIFF')
    sys.exit(0 if ok else 1)
main()
import re, sys
s = open(sys.argv[1]).read()
s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
m = {}
def rep(mo):
    g = mo.group(0)
    if g not in m:
        m[g] = "GUID-%d" % (len(m)+1)
    return m[g]
s = re.sub(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', rep, s)
sys.stdout.write(s)

//! A session: the project, its file, and its undo history; commands run here.

use crate::json::Value;
use crate::project::Project;

pub struct Step {
    pub before: Project,
    pub after: Project,
    pub label: String,
}

pub struct Session {
    pub project: Project,
    pub path: Option<String>,
    pub undo: Vec<Step>,
    pub redo: Vec<Step>,
    pub read_only: bool,
    /// The phase and design option this session makes elements in.
    pub now_phase: Option<String>,
    pub now_option: Option<String>,
}

pub const MAX_UNDO: usize = 200;

impl Session {
    pub fn new() -> Session {
        Session {
            project: Project::new("en"),
            path: None,
            undo: Vec::new(),
            redo: Vec::new(),
            read_only: false,
            now_phase: None,
            now_option: None,
        }
    }

    /// Runs a command by id (or alias, any case) with its parameters.
    pub fn execute(&mut self, id: &str, params: &Value) -> Result<Value, String> {
        let Some((cid, label)) = crate::commands::resolve(id) else {
            return Err(format!("unknown command `{}`; list_commands shows them", id));
        };
        let before = self.project.clone();
        // the phase and option this session makes elements in go back with a refused command
        let now_before = (self.now_phase.clone(), self.now_option.clone());
        let res = crate::commands::run(self, &cid, params);
        match res {
            Ok(out) => {
                if crate::commands::changes_model(&cid) && !crate::commands::is_history_cmd(&cid) {
                    // a scan nothing places any more goes with the command that left it so
                    crate::cloud::drop_unplaced(&mut self.project);
                    // what a constrained dimension measures to follows what the command moved
                    if let Err(e) = crate::views::keep(&mut self.project) {
                        self.project = before;
                        (self.now_phase, self.now_option) = now_before;
                        return Err(e);
                    }
                    if let Err(e) = crate::check::check(&self.project) {
                        self.project = before;
                        (self.now_phase, self.now_option) = now_before;
                        return Err(e);
                    }
                    if self.project.to_value() != before.to_value() || crate::commands::always_step(&cid) {
                        self.undo.push(Step { before, after: self.project.clone(), label: label.clone() });
                        if self.undo.len() > MAX_UNDO {
                            self.undo.remove(0);
                        }
                        self.redo.clear();
                    }
                }
                Ok(out)
            }
            Err(e) => {
                self.project = before;
                (self.now_phase, self.now_option) = now_before;
                Err(e)
            }
        }
    }

    pub fn history(&self) -> Vec<String> {
        self.undo.iter().map(|s| s.label.clone()).collect()
    }
}
//! The model's rules, checked after every command that changes it.

use crate::project::Project;

pub fn check(pr: &Project) -> Result<(), String> {
    core_check(pr)?;
    crate::cloud::check(pr)?;
    crate::media::check(pr)?;
    crate::styles::check(pr)?;
    crate::arch::check(pr)?;
    crate::structure::check(pr)?;
    crate::views::check(pr)?;
    crate::edit::check(pr)?;
    crate::readers::check(pr)?;
    Ok(())
}

fn core_check(pr: &Project) -> Result<(), String> {
    let mut level_names: Vec<String> = Vec::new();
    let mut grid_names: Vec<String> = Vec::new();
    for (id, e) in &pr.elements {
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        match cat {
            "level" => {
                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
                if level_names.contains(&name) {
                    return Err(format!("level {}: another level is already named `{}`", id, name));
                }
                level_names.push(name);
                if let Some(ext) = e.get("extent").and_then(|x| x.as_arr()) {
                    let a = ext.first().and_then(crate::commands::params::point_of);
                    let b = ext.get(1).and_then(crate::commands::params::point_of);
                    if let (Some(a), Some(b)) = (a, b) {
                        if !(b[0] - a[0] > 1.0 && b[1] - a[1] > 1.0) {
                            return Err(format!(
                                "level {}: its extent runs from its south-west corner to its north-east one",
                                id
                            ));
                        }
                    }
                }
            }
            "grid" => {
                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
                if grid_names.contains(&name) {
                    return Err(format!("grid {}: another grid is already named `{}`", id, name));
                }
                grid_names.push(name);
                let a = e.get("start").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
                let b = e.get("end").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
                let len = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
                if len <= 1.0 {
                    return Err(format!("grid {}: too short ({} mm)", id, len));
                }
            }
            _ => {}
        }
    }
    Ok(())
}
//! Common lookups on the model: levels, elements by id or GUID.

use crate::json::Value;
use crate::project::Project;

/// Levels from the lowest up (ties by id).
pub fn levels(pr: &Project) -> Vec<u64> {
    crate::commands::basic::level_ids_sorted(pr)
}

pub fn elev(pr: &Project, level: u64) -> f64 {
    pr.el(level).and_then(|e| e.get("elevation")).and_then(|x| x.as_f64()).unwrap_or(0.0)
}

pub fn name(pr: &Project, id: u64) -> String {
    pr.el(id).and_then(|e| e.get("name")).and_then(|x| x.as_str()).unwrap_or("").to_string()
}

/// The lowest level, where commands go without one.
pub fn default_level(pr: &Project) -> Option<u64> {
    levels(pr).first().copied()
}

/// The next level up from one, if any.
pub fn level_above(pr: &Project, level: u64) -> Option<u64> {
    let ls = levels(pr);
    let i = ls.iter().position(|l| *l == level)?;
    ls.get(i + 1).copied()
}

/// An element by its id (a number or a string of one) or its GUID.
pub fn find(pr: &Project, v: &Value) -> Option<u64> {
    match v {
        Value::Num(_) => {
            let id = crate::commands::params::id_of(v)?;
            if pr.elements.contains_key(&id) {
                Some(id)
            } else {
                None
            }
        }
        Value::Str(s) => {
            let t = s.trim();
            if let Ok(id) = t.parse::<u64>() {
                return if pr.elements.contains_key(&id) { Some(id) } else { None };
            }
            let g = normalize_guid(t)?;
            pr.find_guid(&g)
        }
        _ => None,
    }
}

/// A GUID as the model keeps it (lowercase, hyphenated), from one with or without braces and dashes.
pub fn normalize_guid(s: &str) -> Option<String> {
    let t = s.trim().trim_start_matches('{').trim_end_matches('}');
    let hex: String = t.chars().filter(|c| *c != '-').collect();
    if hex.len() != 32 || !hex.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    let h = hex.to_lowercase();
    Some(format!("{}-{}-{}-{}-{}", &h[0..8], &h[8..12], &h[12..16], &h[16..20], &h[20..32]))
}

/// A level (or a plan view, whose level it is) given by name, id or GUID.
pub fn resolve_level(pr: &Project, cmd: &str, key: &str, v: &Value) -> Result<u64, String> {
    let not = || format!("{}: `{}`: {} is not a level or a plan view", cmd, key, v.to_compact());
    match v {
        Value::Num(_) => {
            let id = find(pr, v).ok_or_else(not)?;
            level_of_view(pr, id).ok_or_else(not)
        }
        Value::Str(s) => {
            if let Some(id) = find(pr, v) {
                return level_of_view(pr, id).ok_or_else(not);
            }
            if s.trim().parse::<u64>().is_ok() || normalize_guid(s).is_some() {
                return Err(not());
            }
            for id in levels(pr) {
                if name(pr, id) == *s {
                    return Ok(id);
                }
            }
            for id in pr.ids_of("planview") {
                if name(pr, id) == *s {
                    if let Some(l) = level_of_view(pr, id) {
                        return Ok(l);
                    }
                }
            }
            let names: Vec<String> = levels(pr).iter().map(|l| name(pr, *l)).collect();
            Err(format!(
                "{}: no level or plan view named `{}` (the levels are: {})",
                cmd,
                s,
                names.join(", ")
            ))
        }
        _ => Err(not()),
    }
}

/// The level of a level, or of a plan view.
pub fn level_of_view(pr: &Project, id: u64) -> Option<u64> {
    match pr.category(id)? {
        "level" => Some(id),
        "planview" => {
            let g = pr.el(id)?.get("level")?.as_str()?.to_string();
            pr.find_guid(&g)
        }
        _ => None,
    }
}

/// A level from the params' `key`, else the lowest.
pub fn level_param(pr: &Project, cmd: &str, p: &Value, key: &str) -> Result<u64, String> {
    match crate::commands::params::get(p, key) {
        Some(v) => resolve_level(pr, cmd, key, v),
        None => default_level(pr).ok_or_else(|| format!("{}: the project has no level", cmd)),
    }
}

//! Reading a command's parameters, with the errors the commands give.

use crate::json::Value;

pub type R<T> = Result<T, String>;

pub fn get<'a>(p: &'a Value, key: &str) -> Option<&'a Value> {
    match p.get(key) {
        Some(Value::Null) | None => None,
        Some(v) => Some(v),
    }
}

pub fn has(p: &Value, key: &str) -> bool {
    get(p, key).is_some()
}

/// Present in the object, even as null.
pub fn given(p: &Value, key: &str) -> bool {
    p.get(key).is_some()
}

pub fn num_of(v: &Value) -> Option<f64> {
    match v {
        Value::Num(n) => Some(n.as_f64()),
        _ => None,
    }
}

/// The largest length a command takes, in mm (1000 km).
pub const MAX_MM: f64 = 1e9;

/// A length in mm, within the model's reach.
pub fn mm_of(v: &Value) -> Option<f64> {
    let x = num_of(v)?;
    if x.is_finite() && x.abs() <= MAX_MM {
        Some(x)
    } else {
        None
    }
}

pub fn req_num(p: &Value, cmd: &str, key: &str) -> R<f64> {
    match get(p, key) {
        None => Err(format!("{}: `{}` in mm is required", cmd, key)),
        Some(v) => mm_of(v).ok_or_else(|| format!("{}: `{}` must be a number in mm, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_num(p: &Value, cmd: &str, key: &str) -> R<Option<f64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => mm_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a number in mm, got {}", cmd, key, v.to_compact())),
    }
}

/// A number in some unit other than mm (degrees, percent…).
pub fn opt_num_unit(p: &Value, cmd: &str, key: &str, unit: &str) -> R<Option<f64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => num_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a number{}, got {}", cmd, key, unit, v.to_compact())),
    }
}

pub fn opt_text(p: &Value, cmd: &str, key: &str) -> R<Option<String>> {
    match get(p, key) {
        None => Ok(None),
        Some(Value::Str(s)) if s.chars().count() <= 256 => Ok(Some(s.clone())),
        Some(v) => Err(format!("{}: `{}` must be text of at most 256 characters, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_bool(p: &Value, cmd: &str, key: &str) -> R<Option<bool>> {
    match get(p, key) {
        None => Ok(None),
        Some(Value::Bool(b)) => Ok(Some(*b)),
        Some(v) => Err(format!("{}: `{}` must be true or false, got {}", cmd, key, v.to_compact())),
    }
}

pub fn point_of(v: &Value) -> Option<[f64; 2]> {
    let a = v.as_arr()?;
    if a.len() != 2 {
        return None;
    }
    Some([mm_of(&a[0])?, mm_of(&a[1])?])
}

pub fn point3_of(v: &Value) -> Option<[f64; 3]> {
    let a = v.as_arr()?;
    if a.len() != 3 {
        return None;
    }
    Some([mm_of(&a[0])?, mm_of(&a[1])?, mm_of(&a[2])?])
}

pub fn req_point(p: &Value, cmd: &str, key: &str) -> R<[f64; 2]> {
    match get(p, key) {
        None => Err(format!("{}: `{}` [x, y] is required", cmd, key)),
        Some(v) => point_of(v).ok_or_else(|| format!("{}: `{}` must be a point [x, y] in mm, got {}", cmd, key, v.to_compact())),
    }
}

pub fn opt_point(p: &Value, cmd: &str, key: &str) -> R<Option<[f64; 2]>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => point_of(v)
            .map(Some)
            .ok_or_else(|| format!("{}: `{}` must be a point [x, y] in mm, got {}", cmd, key, v.to_compact())),
    }
}

/// A list of points; anything but a list of points reads as missing.
pub fn points_of(v: &Value) -> Option<Vec<[f64; 2]>> {
    let a = v.as_arr()?;
    a.iter().map(point_of).collect()
}

pub fn req_points(p: &Value, cmd: &str, key: &str) -> R<Vec<[f64; 2]>> {
    match get(p, key).and_then(points_of) {
        None => Err(format!("{}: `{}` [[x, y], …] is required", cmd, key)),
        Some(v) => Ok(v),
    }
}

pub fn opt_points(p: &Value, cmd: &str, key: &str) -> R<Option<Vec<[f64; 2]>>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => match points_of(v) {
            Some(pts) => Ok(Some(pts)),
            None => Err(format!("{}: `{}` [[x, y], …] is required", cmd, key)),
        },
    }
}

/// An element id: a number, or a GUID or an id in a string.
pub fn id_of(v: &Value) -> Option<u64> {
    match v {
        Value::Num(n) => {
            let f = n.as_f64();
            if f >= 0.0 && f.fract() == 0.0 {
                Some(f as u64)
            } else {
                None
            }
        }
        Value::Str(s) => s.trim().parse::<u64>().ok(),
        _ => None,
    }
}
//! The commands: their registry, dispatch, and the project-level ones.

pub mod basic;
pub mod params;

use crate::json::Value;
use crate::session::Session;
use std::sync::OnceLock;

pub struct CmdInfo {
    pub id: String,
    pub label: String,
    pub aliases: Vec<String>,
}

fn registry() -> &'static Vec<CmdInfo> {
    static REG: OnceLock<Vec<CmdInfo>> = OnceLock::new();
    REG.get_or_init(|| {
        let v = crate::json::parse(crate::catalog::CATALOG).unwrap();
        v.as_arr()
            .unwrap()
            .iter()
            .map(|c| CmdInfo {
                id: c.get("id").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                label: c.get("label").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                aliases: c
                    .get("aliases")
                    .and_then(|x| x.as_arr())
                    .map(|a| a.iter().filter_map(|s| s.as_str().map(|s| s.to_string())).collect())
                    .unwrap_or_default(),
            })
            .collect()
    })
}

/// A command's id and label, from its id or one of its aliases, in any case.
pub fn resolve(id: &str) -> Option<(String, String)> {
    let reg = registry();
    let low = id.to_lowercase();
    if let Some(c) = reg.iter().find(|c| c.id.to_lowercase() == low) {
        return Some((c.id.clone(), c.label.clone()));
    }
    if let Some(c) = reg.iter().find(|c| c.aliases.iter().any(|a| a.to_lowercase() == low)) {
        return Some((c.id.clone(), c.label.clone()));
    }
    None
}

pub fn label_of(cid: &str) -> String {
    registry().iter().find(|c| c.id == cid).map(|c| c.label.clone()).unwrap_or_default()
}

/// Commands that only read the model (no undo step, no check).
pub fn changes_model(cid: &str) -> bool {
    !matches!(
        cid,
        "inspect"
            | "elements"
            | "render"
            | "measure"
            | "library"
            | "select_by_id"
            | "ids_of"
            | "filter_selection"
            | "sketch"
            | "save"
            | "autosave"
            | "circuit"
            | "conduit_fill"
            | "drain_size"
            | "vent_size"
            | "hydrant_size"
            | "load_points"
            | "water_size"
            | "storm_size"
            | "export_fill_patterns"
            | "cad_query"
    )
}

/// Undo and redo move the history themselves; opening a project starts a new one.
pub fn is_history_cmd(cid: &str) -> bool {
    matches!(cid, "undo" | "redo" | "new" | "open" | "recover" | "highrise")
}

pub fn always_step(cid: &str) -> bool {
    // some commands make an undo step even when the model is unchanged; each module owns its own
    crate::media::always_step(cid) || crate::styles::step_anyway(cid) || crate::views::always_step(cid)
}

pub fn run(s: &mut Session, cid: &str, p: &Value) -> Result<Value, String> {
    if s.read_only && changes_model(cid) && !matches!(cid, "save") {
        return Err(format!("{}: this project is open read-only, so it can't be changed", cid));
    }
    if let Some(r) = crate::cloud::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::media::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::styles::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::arch::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::structure::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::views::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::edit::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::readers::dispatch(s, cid, p) {
        return r;
    }
    basic::run(s, cid, p)
}

pub fn io_err(e: &std::io::Error) -> String {
    e.to_string()
}

pub fn open_path(s: &mut Session, path: &str) -> Result<Value, String> {
    basic::open_path(s, path)
}

pub fn info(path: &str) -> Result<Value, String> {
    basic::info(path)
}

pub fn build_sample(s: &mut Session) -> Result<(), String> {
    basic::build_sample(s)
}

pub fn build_highrise(s: &mut Session, storeys: u64) -> Result<Value, String> {
    basic::build_highrise(s, storeys)
}

pub fn mcp_main(args: &[String]) {
    crate::mcp::main(args)
}

//! The project: its library and its elements, held as the JSON a project file holds.

use crate::json::{Map, Value};
use std::collections::BTreeMap;

pub const FORMAT: u64 = 17;

#[derive(Clone)]
pub struct Project {
    /// Top-level keys in file order; `elements` and `library` stand in place as nulls.
    pub doc: Map,
    pub elements: BTreeMap<u64, Value>,
    pub library: BTreeMap<u64, Value>,
    /// The lowest library id handed out since the project was read: ids are never handed out twice,
    /// even once what had one is gone (an undo takes it back with the rest).
    pub lib_low: u64,
}

pub const LANGS: &[&str] = &["en", "pt", "es", "sv", "cs", "fr", "nl", "de", "it"];

fn template(lang: &str) -> &'static str {
    use crate::templates as t;
    match lang {
        "pt" => t::PT,
        "es" => t::ES,
        "sv" => t::SV,
        "cs" => t::CS,
        "fr" => t::FR,
        "nl" => t::NL,
        "de" => t::DE,
        "it" => t::IT,
        _ => t::EN,
    }
}

/// Replaces the `@G<n>` placeholders of a template with GUIDs made now, the same n the same GUID.
fn fill_guids(v: &mut Value, made: &mut Vec<Option<String>>) {
    match v {
        Value::Str(s) => {
            if let Some(n) = s.strip_prefix("@G") {
                if let Ok(n) = n.parse::<usize>() {
                    if made.len() <= n {
                        made.resize(n + 1, None);
                    }
                    if made[n].is_none() {
                        made[n] = Some(crate::rand::guid());
                    }
                    *s = made[n].clone().unwrap();
                }
            }
        }
        Value::Arr(a) => a.iter_mut().for_each(|x| fill_guids(x, made)),
        Value::Obj(m) => m.items.iter_mut().for_each(|(_, x)| fill_guids(x, made)),
        _ => {}
    }
}

pub fn new_uid() -> u64 {
    crate::rand::next_u64()
}

impl Project {
    pub fn new(lang: &str) -> Project {
        let mut v = crate::json::parse(template(lang)).expect("template");
        let mut made = Vec::new();
        fill_guids(&mut v, &mut made);
        let mut p = Project::from_value(v);
        p.doc.insert("uid", Value::u(new_uid()));
        p
    }

    pub fn from_value(v: Value) -> Project {
        let mut doc = match v {
            Value::Obj(m) => m,
            _ => Map::new(),
        };
        let mut elements = BTreeMap::new();
        let mut library = BTreeMap::new();
        if let Some(Value::Obj(m)) = doc.get_mut("elements").map(std::mem::take) {
            for (k, e) in m.items {
                if let Ok(id) = k.parse::<u64>() {
                    elements.insert(id, e);
                }
            }
        }
        if let Some(Value::Obj(m)) = doc.get_mut("library").map(std::mem::take) {
            for (k, e) in m.items {
                if let Ok(id) = k.parse::<u64>() {
                    library.insert(id, e);
                }
            }
        }
        if !doc.contains("elements") {
            doc.insert("elements", Value::Null);
        }
        if !doc.contains("library") {
            doc.insert("library", Value::Null);
        }
        Project { doc, elements, library, lib_low: 1_000_000 }
    }

    pub fn to_value(&self) -> Value {
        let mut out = Map::new();
        for (k, v) in &self.doc.items {
            if k == "elements" {
                let mut m = Map::new();
                for (id, e) in &self.elements {
                    m.items.push((id.to_string(), e.clone()));
                }
                out.items.push((k.clone(), Value::Obj(m)));
            } else if k == "library" {
                let mut m = Map::new();
                for (id, e) in &self.library {
                    m.items.push((id.to_string(), e.clone()));
                }
                out.items.push((k.clone(), Value::Obj(m)));
            } else {
                out.items.push((k.clone(), v.clone()));
            }
        }
        Value::Obj(out)
    }

    pub fn to_file_string(&self) -> String {
        self.to_value().to_pretty()
    }

    // ------------------------------------------------------------ top level

    pub fn get(&self, k: &str) -> Option<&Value> {
        self.doc.get(k)
    }
    pub fn get_mut(&mut self, k: &str) -> Option<&mut Value> {
        self.doc.get_mut(k)
    }
    pub fn name(&self) -> String {
        self.doc.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string()
    }
    pub fn language(&self) -> String {
        self.doc.get("language").and_then(|v| v.as_str()).unwrap_or("en").to_string()
    }
    /// A section of the file (`types`, `materials`…), made where the canonical order puts it.
    pub fn section_mut(&mut self, k: &str) -> &mut Map {
        if !self.doc.contains(k) {
            self.insert_top(k, Value::obj());
        }
        let v = self.doc.get_mut(k).unwrap();
        if !matches!(v, Value::Obj(_)) {
            *v = Value::obj();
        }
        v.as_obj_mut().unwrap()
    }
    pub fn section(&self, k: &str) -> Option<&Map> {
        self.doc.get(k).and_then(|v| v.as_obj())
    }
    /// Inserts a top-level key at its place in the file's order.
    pub fn insert_top(&mut self, k: &str, v: Value) {
        if self.doc.contains(k) {
            self.doc.insert(k, v);
            return;
        }
        let order = TOP_ORDER;
        let rank = |key: &str| order.iter().position(|o| *o == key).unwrap_or(usize::MAX);
        let r = rank(k);
        let pos = self.doc.items.iter().position(|(kk, _)| rank(kk) > r).unwrap_or(self.doc.items.len());
        self.doc.items.insert(pos, (k.to_string(), v));
    }
    pub fn remove_top(&mut self, k: &str) {
        self.doc.remove(k);
    }

    // ------------------------------------------------------------ ids

    pub fn next_id(&self) -> u64 {
        self.doc.get("next_id").and_then(|v| v.as_u64()).unwrap_or(100000)
    }
    pub fn alloc_id(&mut self) -> u64 {
        let mut id = self.next_id();
        while self.elements.contains_key(&id) {
            id += 1;
        }
        self.doc.insert("next_id", Value::u(id + 1));
        id
    }

    /// The lowest id the library and its parts use.
    pub fn lowest_lib_id(&self) -> u64 {
        let mut low = 1_000_000u64;
        if let Some(k) = self.library.keys().next() {
            low = low.min(*k);
        }
        fn scan(v: &Value, low: &mut u64) {
            match v {
                Value::Obj(m) => {
                    if let Some(Value::Num(n)) = m.get("id") {
                        let x = n.as_f64();
                        if x >= 900000.0 && x < 1_000_000.0 {
                            *low = (*low).min(x as u64);
                        }
                    }
                    for (_, x) in &m.items {
                        scan(x, low);
                    }
                }
                Value::Arr(a) => a.iter().for_each(|x| scan(x, low)),
                _ => {}
            }
        }
        for (k, v) in &self.doc.items {
            if k != "elements" && k != "library" {
                scan(v, &mut low);
            }
        }
        // the parts elements hold (a region's sketch lines…) count down from the same ids
        for e in self.elements.values() {
            scan(e, &mut low);
        }
        low
    }
    pub fn alloc_lib_id(&mut self) -> u64 {
        let id = self.lowest_lib_id().min(self.lib_low) - 1;
        self.lib_low = id;
        id
    }

    // ------------------------------------------------------------ elements

    pub fn el(&self, id: u64) -> Option<&Value> {
        self.elements.get(&id)
    }
    pub fn el_mut(&mut self, id: u64) -> Option<&mut Value> {
        self.elements.get_mut(&id)
    }
    pub fn category(&self, id: u64) -> Option<&str> {
        self.elements.get(&id).and_then(|e| e.get("category")).and_then(|c| c.as_str())
    }
    pub fn guid_of(&self, id: u64) -> Option<String> {
        self.elements.get(&id).and_then(|e| e.get("guid")).and_then(|g| g.as_str()).map(|s| s.to_string())
    }
    pub fn find_guid(&self, g: &str) -> Option<u64> {
        self.elements
            .iter()
            .find(|(_, e)| e.get("guid").and_then(|x| x.as_str()) == Some(g))
            .map(|(id, _)| *id)
    }
    pub fn ids_of(&self, cat: &str) -> Vec<u64> {
        self.elements
            .iter()
            .filter(|(_, e)| e.get("category").and_then(|c| c.as_str()) == Some(cat))
            .map(|(id, _)| *id)
            .collect()
    }

    // ------------------------------------------------------------ library

    pub fn lib_find_guid(&self, g: &str) -> Option<u64> {
        self.library
            .iter()
            .find(|(_, e)| e.get("guid").and_then(|x| x.as_str()) == Some(g))
            .map(|(id, _)| *id)
    }
    pub fn lib_find(&self, kind: &str, name: &str) -> Option<u64> {
        self.library
            .iter()
            .find(|(_, e)| {
                e.get("kind").and_then(|x| x.as_str()) == Some(kind) && e.get("name").and_then(|x| x.as_str()) == Some(name)
            })
            .map(|(id, _)| *id)
    }
    pub fn lib_guid(&self, kind: &str, name: &str) -> Option<String> {
        let id = self.lib_find(kind, name)?;
        self.library.get(&id).and_then(|e| e.get("guid")).and_then(|g| g.as_str()).map(|s| s.to_string())
    }
    /// The name of the library entry with this GUID.
    pub fn lib_name(&self, g: &str) -> Option<String> {
        let id = self.lib_find_guid(g)?;
        self.library.get(&id).and_then(|e| e.get("name")).and_then(|g| g.as_str()).map(|s| s.to_string())
    }
    pub fn lib_add(&mut self, kind: &str, name: &str) -> (u64, String) {
        let id = self.alloc_lib_id();
        let g = crate::rand::guid();
        self.library.insert(id, crate::jobj! {"kind" => kind, "name" => name, "guid" => g.clone()});
        (id, g)
    }
}

