cd /tmp/views-view3d && python3 -c "
import json, collections; d=json.load(open('/tmp/views-view3d/kinds.bimcraft'))
f=d['families']
keys=collections.Counter(); planes=collections.Counter(); exprs=set()
for name,fam in f.items():
    for fm in fam.get('forms',[]):
        keys[tuple(sorted(fm.keys()))]+=1
        planes[fm.get('plane')]+=1
        for k in ('from','to'):
            if isinstance(fm.get(k),str): exprs.add(fm[k])
        for p in fm.get('profile',[]):
            for c in p:
                if isinstance(c,str): exprs.add(c)
    for k in fam.keys():
        if k not in ('category','parameters','types','forms'): print('famkey', name, k, json.dumps(fam[k])[:300])
print(keys); print(planes)
import re
toks=set()
for e in exprs:
    for t in re.findall(r'[A-Za-z_][A-Za-z_ 0-9]*|[^A-Za-z_0-9\s.]', e): toks.add(t.strip())
print(sorted(toks))
"

