#!/usr/bin/env python3
"""Run each line of a command file in fresh runs of the original and mine; compare stdout, stderr, exit
code and the saved project (normalised GUIDs). usage: cmpall.py [-f in.bimcraft] [-v] cmds.txt
A line is commands joined by ' ;; '. Every run saves out.bimcraft at the end."""
import os, re, subprocess, sys, tempfile, shutil, json, difflib
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/workspace/.claude/worktrees/agent-a8c36a3716c77cdcf/target/release/bimcraft-cli')
G = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    return G.sub(rep, s)
a = sys.argv[1:]
infile = None; verbose = False; nosave = False
while a and a[0].startswith('-'):
    if a[0] == '-f': infile = a[1]; a = a[2:]
    elif a[0] == '-v': verbose = True; a = a[1:]
    elif a[0] == '-n': nosave = True; a = a[1:]
    else: break
lines = [l.rstrip('\n') for l in open(a[0]) if l.strip() and not l.startswith('#')]
same = 0
for l in lines:
    outs = []
    for exe in (ORIG, MINE):
        d = tempfile.mkdtemp(prefix='c', dir='/tmp/views-view3d/scratch')
        args = [exe, 'run']
        if infile:
            shutil.copy(infile, d)
            args.append(os.path.basename(infile))
        for c in l.split(' ;; '):
            args += ['--cmd', c]
        if not nosave:
            args += ['--save', 'out.bimcraft']
        p = subprocess.run(args, cwd=d, capture_output=True, timeout=300)
        o = p.stdout.decode('utf-8', 'replace')
        o = '\n'.join(x for x in o.split('\n') if not x.startswith('{"format":"bimcraft"') and not (infile and x.startswith('{"name":') and '"path"' in x))
        f = ''
        fp = os.path.join(d, 'out.bimcraft')
        if os.path.exists(fp):
            f = open(fp).read()
        shutil.rmtree(d)
        outs.append((norm(o), norm(p.stderr.decode('utf-8', 'replace')), p.returncode, norm(f)))
    if outs[0] == outs[1]:
        same += 1
        if verbose: print('SAME', l[:200])
    else:
        print('DIFF', l)
        names = ['stdout', 'stderr', 'code', 'file']
        for i in range(4):
            if outs[0][i] != outs[1][i]:
                x = str(outs[0][i]).splitlines(); y = str(outs[1][i]).splitlines()
                for dl in list(difflib.unified_diff(x, y, 'orig', 'mine', lineterm='', n=1))[2:40]:
                    print('   ', names[i], dl[:400])
print('%d/%d same' % (same, len(lines)))

