#!/usr/bin/env python3
"""Each line: SETUP || TEST (commands joined by ' ;; '). The setup runs on the original (from an
optional -f base file) and is saved; the test runs on both programs from that file, saving out.bimcraft;
stdout/stderr/code/file compared (GUIDs normalised). usage: cmpset.py [-f base.bimcraft] [-v] file"""
import os, re, subprocess, sys, tempfile, shutil, difflib
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/workspace/.claude/worktrees/agent-a8c36a3716c77cdcf/target/release/bimcraft-cli')
G = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    return G.sub(rep, s)
a = sys.argv[1:]
base = None; verbose = False
while a and a[0].startswith('-'):
    if a[0] == '-f': base = a[1]; a = a[2:]
    elif a[0] == '-v': verbose = True; a = a[1:]
    else: break
lines = [l.rstrip('\n') for l in open(a[0]) if l.strip() and not l.startswith('#')]
same = 0
for l in lines:
    if ' || ' in l:
        setup, test = l.split(' || ', 1)
    else:
        setup, test = '', l
    d0 = tempfile.mkdtemp(prefix='s', dir='/tmp/views-view3d/scratch')
    args = [ORIG, 'run']
    if base:
        shutil.copy(base, d0); args.append(os.path.basename(base))
    for c in [x for x in setup.split(' ;; ') if x.strip()]:
        args += ['--cmd', c]
    args += ['--save', 'in.bimcraft']
    p = subprocess.run(args, cwd=d0, capture_output=True, timeout=300)
    if p.returncode != 0:
        print('SETUP FAILED', setup, p.stderr.decode()[:300]); shutil.rmtree(d0); continue
    inf = os.path.join(d0, 'in.bimcraft')
    outs = []
    for exe in (ORIG, MINE):
        d = tempfile.mkdtemp(prefix='c', dir='/tmp/views-view3d/scratch')
        shutil.copy(inf, d)
        args = [exe, 'run', 'in.bimcraft']
        for c in test.split(' ;; '):
            args += ['--cmd', c]
        args += ['--save', 'out.bimcraft']
        p = subprocess.run(args, cwd=d, capture_output=True, timeout=300)
        o = p.stdout.decode('utf-8', 'replace')
        o = '\n'.join(x for x in o.split('\n')[1:] if not x.startswith('{"format":"bimcraft"'))
        f = ''
        fp = os.path.join(d, 'out.bimcraft')
        if os.path.exists(fp):
            f = open(fp).read()
        shutil.rmtree(d)
        outs.append((norm(o), norm(p.stderr.decode('utf-8', 'replace')), p.returncode, norm(f)))
    shutil.rmtree(d0)
    if outs[0] == outs[1]:
        same += 1
        if verbose: print('SAME', l[:200])
    else:
        print('DIFF', l)
        names = ['stdout', 'stderr', 'code', 'file']
        for i in range(4):
            if outs[0][i] != outs[1][i]:
                x = str(outs[0][i]).splitlines(); y = str(outs[1][i]).splitlines()
                for dl in list(difflib.unified_diff(x, y, 'orig', 'mine', lineterm='', n=1))[2:30]:
                    print('   ', names[i], dl[:400])
print('%d/%d same' % (same, len(lines)))

