430	// ---------------------------------------------------------------- roofs
431	
432	/// A roof by footprint: its outline and courtyards, and each edge's slope (none: a gable).
433	#[derive(Clone, Debug)]
434	pub struct RoofGeo {
435	    pub outline: Vec<P2>,
436	    pub holes: Vec<Vec<P2>>,
437	    /// Each edge: a point of it, its inward unit normal, its slope in degrees (none: upright).
438	    pub edges: Vec<(P2, P2, Option<f64>)>,
439	    pub base: f64,
440	    pub overhang: f64,
441	    pub slope: f64,
442	    pub thickness: f64,
443	}
444	
445	fn roof_geo(pr: &Project, e: &Value) -> Option<RoofGeo> {
446	    let outline = pts(e.get("boundary"));
447	    if outline.len() < 3 {
448	        return None;
449	    }
450	    let holes = loops(e.get("courtyards"));
451	    let slope = f_of(e, "slope").unwrap_or(0.0);
452	    let overhang = f_of(e, "overhang").unwrap_or(0.0);
453	    let base = base_z(pr, e) + f_of(e, "offset").unwrap_or(0.0);
454	    let thickness = lib_type(pr, e, &["roof"]).and_then(|t| f_of(t, "thickness")).unwrap_or(300.0);
455	    let mut gables: Vec<usize> = e
456	        .get("gables")
457	        .and_then(|g| g.as_arr())
458	        .map(|a| a.iter().filter_map(|x| x.as_f64()).map(|x| x as usize).collect())
459	        .unwrap_or_default();
460	    if e.get("gable").and_then(|g| g.as_bool()) == Some(true) && outline.len() == 4 {
461	        let l: Vec<f64> = (0..4).map(|i| vm::dist(outline[i], outline[(i + 1) % 4])).collect();
462	        if l[0] + l[2] <= l[1] + l[3] {
463	            gables.extend([0, 2]);
464	        } else {
465	            gables.extend([1, 3]);
466	        }
467	    }
468	    let slopes: Vec<f64> = e
469	        .get("slopes")
470	        .and_then(|s| s.as_arr())
471	        .map(|a| a.iter().filter_map(|x| x.as_f64()).collect())
472	        .unwrap_or_default();
473	    let mut edges = Vec::new();
474	    let mut k = 0usize;
475	    let mut ring = |poly: &Vec<P2>, hole: bool, edges: &mut Vec<(P2, P2, Option<f64>)>| {
476	        let ccw = area2(poly) > 0.0;
477	        // the roof lies left of an outline running counter-clockwise, right of a courtyard's
478	        let left = ccw != hole;
479	        let n = poly.len();
480	        for i in 0..n {
481	            let a = poly[i];
482	            let b = poly[(i + 1) % n];
483	            let ln = vm::left_normal(a, b);
484	            let inward = if left { ln } else { vm::mul(ln, -1.0) };
485	            let s = if gables.contains(&k) {
486	                None
487	            } else {
488	                let own = slopes.get(k).cloned().unwrap_or(0.0);
489	                Some(if own == 0.0 { slope } else { own })
490	            };
491	            edges.push((a, inward, s));
492	            k += 1;
493	        }
494	    };
495	    ring(&outline, false, &mut edges);
496	    for h in &holes {
497	        ring(h, true, &mut edges);
498	    }
499	    Some(RoofGeo { outline, holes, edges, base, overhang, slope, thickness })
500	}
501	
502	impl RoofGeo {
503	    fn flat(&self) -> bool {
504	        self.slope == 0.0 || self.edges.iter().all(|e| e.2.is_none())
505	    }
506	    /// The sloped edge whose slope the point lies under, and its distance in.
507	    fn face_at(&self, p: P2) -> Option<(usize, f64)> {
508	        let mut best: Option<(usize, f64, f64)> = None;
509	        for (i, (a, n, s)) in self.edges.iter().enumerate() {
510	            let Some(s) = s else { continue };
511	            let d = vm::dot(vm::sub(p, *a), *n);
512	            let h = d * s.to_radians().tan();
513	            if best.map_or(true, |(_, _, bh)| h < bh) {
514	                best = Some((i, d, h));
515	            }
516	        }
517	        best.map(|(i, d, _)| (i, d))
518	    }
519	    /// The underside and the top over a point of it.
520	    pub fn heights(&self, p: P2) -> (f64, f64) {
521	        if self.flat() {
522	            return (self.base, self.base + self.thickness);
523	        }
524	        let Some((i, d)) = self.face_at(p) else { return (self.base, self.base + self.thickness) };
525	        let s = self.edges[i].2.unwrap();
526	        self.heights_on(s, d)
527	    }
528	    fn heights_on(&self, s: f64, d: f64) -> (f64, f64) {
529	        let t = s.to_radians().tan();
530	        let h = self.thickness / s.to_radians().cos();
531	        if s == self.slope {
532	            (self.base + (d - self.overhang) * t, (self.base + h) + (d - self.overhang) * t)
533	        } else {
534	            let o = self.overhang * self.slope.to_radians().tan();
535	            (self.base + d * t - o, (self.base + h) + d * t - o)
536	        }
537	    }
538	    /// How steeply it falls at a point, and the way down in plan (none where it is level).
539	    pub fn slope_at(&self, p: P2) -> (f64, Option<P2>) {
540	        if self.flat() {
541	            return (0.0, None);
542	        }
543	        match self.face_at(p) {
544	            Some((i, _)) => {
545	                let (_, n, s) = self.edges[i];
546	                let s = s.unwrap();
547	                if s == 0.0 {
548	                    (0.0, None)
549	                } else {
550	                    (s.to_radians().tan(), Some([-n[0], -n[1]]))
551	                }
552	            }
553	            None => (0.0, None),
554	        }
555	    }
556	    /// Its highest top: where its slopes meet highest.
557	    fn max_top(&self) -> f64 {
558	        if self.flat() {
559	            return self.base + self.thickness;
560	        }
561	        let mut cands: Vec<P2> = self.outline.clone();
562	        for h in &self.holes {
563	            cands.extend(h.iter().cloned());
564	        }
565	        // where two slopes are as high, along each edge of the outline; where three are
566	        let sloped: Vec<(P2, P2, f64)> =
567	            self.edges.iter().filter_map(|(a, n, s)| s.map(|s| (*a, *n, s.to_radians().tan()))).collect();
568	        let mut rings: Vec<&Vec<P2>> = vec![&self.outline];
569	        rings.extend(self.holes.iter());
570	        for i in 0..sloped.len() {
571	            for j in (i + 1)..sloped.len() {
572	                // h_i(p) = h_j(p): (n_i t_i - n_j t_j) · p = n_i·a_i t_i - n_j·a_j t_j
573	                let (ai, ni, ti) = sloped[i];
574	                let (aj, nj, tj) = sloped[j];
575	                let g = [ni[0] * ti - nj[0] * tj, ni[1] * ti - nj[1] * tj];
576	                let c = vm::dot(ni, ai) * ti - vm::dot(nj, aj) * tj;
577	                for ring in &rings {
578	                    let n = ring.len();
579	                    for k in 0..n {
580	                        let p = ring[k];
581	                        let q = ring[(k + 1) % n];
582	                        let fp = vm::dot(g, p) - c;
583	                        let fq = vm::dot(g, q) - c;
584	                        if (fp <= 0.0 && fq >= 0.0) || (fp >= 0.0 && fq <= 0.0) {
585	                            if fp != fq {
586	                                let t = fp / (fp - fq);
587	                                cands.push([p[0] + (q[0] - p[0]) * t, p[1] + (q[1] - p[1]) * t]);
588	                            }
589	                        }
590	                    }
591	                }
592	                for k in (j + 1)..sloped.len() {
593	                    let (ak, nk, tk) = sloped[k];
594	                    let g2 = [ni[0] * ti - nk[0] * tk, ni[1] * ti - nk[1] * tk];
595	                    let c2 = vm::dot(ni, ai) * ti - vm::dot(nk, ak) * tk;
596	                    let det = g[0] * g2[1] - g[1] * g2[0];
597	                    if det.abs() > 1e-12 {
598	                        let x = (c * g2[1] - g[1] * c2) / det;
599	                        let y = (g[0] * c2 - c * g2[0]) / det;
600	                        cands.push([x, y]);
601	                    }
602	                }
603	            }
604	        }
605	        let mut best = f64::NEG_INFINITY;
606	        for p in cands {
607	            if !self.covers(p) {
608	                continue;
609	            }
610	            let (_, top) = self.heights(p);
611	            best = best.max(top);
612	        }
613	        if best.is_finite() {
614	            best
615	        } else {
616	            self.base + self.thickness
617	        }
