#!/usr/bin/env python3
"""Random models (built by the original) and random spots/section boxes on them, as cmpset lines.
usage: gen_spots.py seed count > file"""
import random, sys, json
seed = int(sys.argv[1]); count = int(sys.argv[2])
random.seed(seed)
def rp(lo, hi):
    return round(random.uniform(lo, hi) / 50) * 50
lines = []
for k in range(count):
    setup = []
    kind = random.choice(['box', 'L', 'box+floor', 'box+roof', 'roof', 'cols', 'stair', 'mix', 'arc', 'tri'])
    W = rp(4000, 12000); D = rp(3000, 9000)
    wt = random.choice(['Generic - 200mm', 'Exterior - 300mm', 'Interior - 100mm'])
    loc = random.choice(['centre', 'exterior-finish', 'interior-finish', 'core-centre'])
    if kind in ('box', 'box+floor', 'box+roof', 'mix'):
        pts = [[0, 0], [W, 0], [W, D], [0, D]]
        if random.random() < 0.5:
            pts = pts[::-1]
        setup.append('wall %s' % json.dumps({"points": pts, "closed": True, "type": wt, "location": loc, "height": rp(2500, 4000)}))
    if kind == 'L':
        pts = [[0, 0], [W, 0], [W, D // 2], [W // 2, D // 2], [W // 2, D], [0, D]]
        setup.append('wall %s' % json.dumps({"points": pts, "closed": True, "type": wt}))
    if kind == 'arc':
        setup.append('wall %s' % json.dumps({"points": [[0, 0], [W, 0]], "arc": random.choice([30, 45, 60, 90, 120, -45, -90])}))
    if kind == 'tri':
        setup.append('wall %s' % json.dumps({"points": [[0, 0], [W, 0], [W // 2, D]], "closed": True}))
    if kind in ('box+floor', 'mix'):
        f = {"boundary": [[0, 0], [W, 0], [W, D], [0, D]], "offset": random.choice([0, 150, -100])}
        if random.random() < 0.3:
            f["slope"] = random.choice([2, 5, -3]); f["arrow"] = [[0, 0], [random.choice([0, W]), D]]
        setup.append('floor %s' % json.dumps(f))
    if kind in ('box+roof', 'roof', 'mix'):
        o = random.choice([0, 300, 500])
        r = {"boundary": [[-o, -o], [W + o, -o], [W + o, D + o], [-o, D + o]], "slope": random.choice([0, 20, 30, 45]), "overhang": o}
        if random.random() < 0.3:
            r["gable"] = True
        setup.append('roof %s' % json.dumps(r))
    if kind in ('cols', 'mix'):
        for i in range(random.randint(1, 3)):
            setup.append('column %s' % json.dumps({"at": [rp(500, W - 500), rp(500, D - 500)], "angle": random.choice([0, 0, 30, 45])}))
    if kind in ('stair', 'mix'):
        setup.append('stair %s' % json.dumps({"start": [rp(500, W / 2), rp(500, D / 2)], "angle": random.choice([0, 90, 180, -90, 30])}))
    tests = []
    for i in range(random.randint(3, 6)):
        view = random.choice([None, None, 'Level 2'])
        p = {"at": [rp(-600, W + 600), rp(-600, D + 600)]}
        if view: p["view"] = view
        tests.append(random.choice(['spot', 'spot', 'spot_slope']) + ' ' + json.dumps(p))
    tests.append('section_box {}')
    tests.append('elements {"category":"spot"}')
    lines.append(' ;; '.join(setup) + ' || ' + ' ;; '.join(tests))
print('\n'.join(lines))

