#!/usr/bin/env python3
"""Split 'SETUP || a ;; b ;; c' lines into one line per test command. usage: split.py in out"""
import sys
out = []
for l in open(sys.argv[1]):
    l = l.rstrip('\n')
    if ' || ' not in l:
        out.append(l); continue
    s, t = l.split(' || ', 1)
    for c in t.split(' ;; '):
        out.append(s + ' || ' + c)
open(sys.argv[2], 'w').write('\n'.join(out) + '\n')

