    let z_of = |q: P2| marks.iter().find(|(m, _)| vm::dist(*m, q) < 1e-6).map(|(_, z)| *z).unwrap_or(0.0);
    let mut out = Vec::new();
    for t in delaunay(&pts) {
        let (a, b, c) = (pts[t[0]], pts[t[1]], pts[t[2]]);
        let g = [(a[0] + b[0] + c[0]) / 3.0, (a[1] + b[1] + c[1]) / 3.0];
