    let mut guard = 0;
    while idx.len() > 3 && guard < 10_000 {
        guard += 1;
        let m = idx.len();
        let mut cut = false;
        for k in 0..m {
            let (a, b, c) = (idx[(k + m - 1) % m], idx[k], idx[(k + 1) % m]);
            let (pa, pb, pc) = (poly[a], poly[b], poly[c]);
            if vm::cross(vm::sub(pb, pa), vm::sub(pc, pb)) <= 0.0 {
                continue;
            }
            let tri = [pa, pb, pc];
            if idx.iter().any(|&q| q != a && q != b && q != c && inside(&tri, poly[q])) {
                continue;
            }
            out.push([a, b, c]);
            idx.remove(k);
            cut = true;
            break;
        }
        if !cut {
            break;
        }
    }
    if idx.len() == 3 {
