        elif kind in ('stair', 'ramp'):
            setup.append(kind + ' ' + json.dumps({"start": [rp(500, W / 2), rp(500, D / 2)], "angle": random.choice([0, 90, 180, 270])}))
        elif kind == 'component':
            setup.append('component ' + json.dumps({"family": random.choice(['Table', 'Bed', 'Chair', 'Sofa', 'Desk', 'Wardrobe']), "at": [rp(500, W - 500), rp(500, D - 500)], "angle": random.choice([0, 90, 180, 45])}))
